package io.tenvyr.control.engine;

import com.fasterxml.jackson.databind.node.ObjectNode;
import io.tenvyr.platform.*;
import java.time.Instant;
import java.util.*;
import static io.tenvyr.control.engine.EngineFacts.*;

public final class AgentEventService {
  public static final class PayloadTooLarge extends RuntimeException{public PayloadTooLarge(){super("AgentEvent payload exceeds 65536 bytes canonical limit");}}
  public record Cursor(Instant receivedAt,String id){} public record Page(List<ObjectNode> events,Cursor next){}
  private final Db db;public AgentEventService(Db db){this.db=db;}
  public String apply(ObjectNode event,ObjectNode transport){if(Json.bytes(event)>65536)throw new PayloadTooLarge();String hash=Json.hash(event);TransportIdentity source=TransportIdentity.of(transport);Instant received=transport.hasNonNull("receivedAt")?Instant.parse(transport.path("receivedAt").asText()):Instant.now();return db.transaction(tx->{ObjectNode attempt=tx.one("SELECT * FROM step_attempts WHERE \"invocationId\"=? FOR UPDATE",event.path("invocationId").asText());if(attempt==null||!attempt.path("executionId").asText().equals(event.path("executionId").asText())||!attempt.path("logicalStepId").asText().equals(event.path("stepExecutionId").asText()))return "ignored";ObjectNode canonical=tx.one("SELECT * FROM agent_events WHERE \"stepAttemptId\"=? AND \"eventId\"=? FOR UPDATE",attempt.path("id").asText(),event.path("eventId").asText());if(canonical!=null){if(canonical.path("payloadHash").asText().equals(hash))return "duplicate";conflict(tx,attempt,event,hash,source,"event_id_payload");return "conflict";}if(tx.exists("SELECT id FROM agent_events WHERE \"stepAttemptId\"=? AND sequence=?",attempt.path("id").asText(),event.path("sequence").asInt())){conflict(tx,attempt,event,hash,source,"sequence_owner");return "conflict";}
    tx.execute("INSERT INTO agent_events (\"stepAttemptId\",\"invocationId\",\"executionId\",\"logicalStepId\",\"eventId\",sequence,type,payload,metadata,trace,\"payloadHash\",\"occurredAt\",\"receivedAt\",\"sourceAdapter\",\"sourceScope\",\"sourceMessageId\") VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT DO NOTHING",attempt.path("id").asText(),event.path("invocationId").asText(),event.path("executionId").asText(),event.path("stepExecutionId").asText(),event.path("eventId").asText(),event.path("sequence").asInt(),event.path("type").asText(),event.get("payload"),event.get("metadata"),event.get("trace"),hash,Instant.parse(event.path("occurredAt").asText()),received,source.adapter(),source.scope(),source.messageId());ObjectNode after=tx.one("SELECT * FROM agent_events WHERE \"stepAttemptId\"=? AND \"eventId\"=?",attempt.path("id").asText(),event.path("eventId").asText());if(after==null||!after.path("payloadHash").asText().equals(hash)){conflict(tx,attempt,event,hash,source,after==null?"sequence_owner":"event_id_payload");return "conflict";}
    if(!TERMINAL_ATTEMPT.contains(attempt.path("status").asText())){ObjectNode fields=Json.object("lastEventReceivedAt",received.toString());String type=event.path("type").asText();switch(type){case "accepted"->fields.put("acceptedAt",received.toString());case "heartbeat"->fields.put("lastHeartbeatReceivedAt",received.toString());case "progress"->fields.put("lastProgressReceivedAt",received.toString());}tx.update("step_attempts",attempt.path("id").asText(),fields);if(Set.of("heartbeat","progress","log","artifact").contains(type))tx.execute("UPDATE step_attempts SET status='RUNNING',\"startTime\"=COALESCE(\"startTime\",now()) WHERE id=? AND status='DISPATCHED'",attempt.path("id").asText());}return "applied";
  });}
  private void conflict(Db tx,ObjectNode attempt,ObjectNode event,String hash,TransportIdentity s,String kind){tx.execute("INSERT INTO agent_event_conflicts (\"stepAttemptId\",\"invocationId\",\"eventId\",sequence,\"conflictKind\",\"payloadHash\",payload,\"sourceAdapter\",\"sourceScope\",\"sourceMessageId\",\"receivedAt\") VALUES (?,?,?,?,?,?,?,?,?,?,now()) ON CONFLICT DO NOTHING",attempt.path("id").asText(),event.path("invocationId").asText(),event.path("eventId").asText(),event.path("sequence").asInt(),kind,hash,event.get("payload"),s.adapter(),s.scope(),s.messageId());}
  public Page list(String executionId,String attemptId,String type,int limit,Cursor after){if(limit<1||limit>200)throw new IllegalArgumentException("Event limit must be 1..200");String sql="SELECT * FROM agent_events WHERE \"executionId\"=?";List<Object> args=new ArrayList<>();args.add(executionId);if(attemptId!=null){sql+=" AND \"stepAttemptId\"=?";args.add(attemptId);}if(type!=null){sql+=" AND type=?";args.add(type);}if(after!=null){sql+=" AND (\"receivedAt\">? OR (\"receivedAt\"=? AND id>?))";args.add(after.receivedAt());args.add(after.receivedAt());args.add(after.id());}sql+=" ORDER BY \"receivedAt\",id LIMIT ?";args.add(limit+1);List<ObjectNode> rows=db.query(sql,args.toArray());boolean more=rows.size()>limit;if(more)rows=new ArrayList<>(rows.subList(0,limit));ObjectNode last=rows.isEmpty()?null:rows.get(rows.size()-1);return new Page(rows,more?new Cursor(instant(last,"receivedAt"),last.path("id").asText()):null);}
}
